// AUTO-GENERATED by scripts/build-artifact.mjs --mode=module - do not edit by hand.
// One flattened ES module version of src/molscene/, for hosts that already
// provide three.js as an importable package (e.g. claude.ai artifacts).
import * as THREE from 'three';

// ---- src/molscene/elements.js ----
// Periodic data used by the engine. Deliberately limited to what's needed
// for bonding/geometry inference and rendering, not a full periodic table.
//
// valence: electrons available for bonding/lone pairs (main-group rule:
//   group 1-2 -> group number, group 13-18 -> group number - 10).
// covalentRadius: single-bond covalent radius in angstrom (Pyykko/Cordero,
//   rounded), used only to scale auto-layout bond lengths.
// dBlock: true marks transition metals, for which automatic Lewis/VSEPR
//   inference is not attempted (see docs/molscene-spec.md, "Limitations").

const ELEMENTS = {
  H:  { z: 1,  valence: 1, covalentRadius: 0.31, color: '#d7e2f0' },
  He: { z: 2,  valence: 2, covalentRadius: 0.28, color: '#8fd6e0' },
  Li: { z: 3,  valence: 1, covalentRadius: 1.28, color: '#b08fe0' },
  Be: { z: 4,  valence: 2, covalentRadius: 0.96, color: '#7fbf7f' },
  B:  { z: 5,  valence: 3, covalentRadius: 0.84, color: '#e0a05f' },
  C:  { z: 6,  valence: 4, covalentRadius: 0.76, color: '#8a93a3' },
  N:  { z: 7,  valence: 5, covalentRadius: 0.71, color: '#4f7fe0' },
  O:  { z: 8,  valence: 6, covalentRadius: 0.66, color: '#e0483a' },
  F:  { z: 9,  valence: 7, covalentRadius: 0.57, color: '#5fd66b' },
  Ne: { z: 10, valence: 8, covalentRadius: 0.58, color: '#8fd6e0' },
  Na: { z: 11, valence: 1, covalentRadius: 1.66, color: '#a97fe0' },
  Mg: { z: 12, valence: 2, covalentRadius: 1.41, color: '#7fbf7f' },
  Al: { z: 13, valence: 3, covalentRadius: 1.21, color: '#a3a9b5' },
  Si: { z: 14, valence: 4, covalentRadius: 1.11, color: '#e0c93f' },
  P:  { z: 15, valence: 5, covalentRadius: 1.07, color: '#e0863f' },
  S:  { z: 16, valence: 6, covalentRadius: 1.05, color: '#e0c93f' },
  Cl: { z: 17, valence: 7, covalentRadius: 1.02, color: '#3fae55' },
  Ar: { z: 18, valence: 8, covalentRadius: 1.06, color: '#8fd6e0' },
  K:  { z: 19, valence: 1, covalentRadius: 2.03, color: '#a97fe0' },
  Ca: { z: 20, valence: 2, covalentRadius: 1.76, color: '#7fbf7f' },
  Br: { z: 35, valence: 7, covalentRadius: 1.20, color: '#b0523f' },
  I:  { z: 53, valence: 7, covalentRadius: 1.39, color: '#8f5fbf' },
  Fe: { z: 26, valence: 2, covalentRadius: 1.32, color: '#d68f3f', dBlock: true },
  Cu: { z: 29, valence: 2, covalentRadius: 1.32, color: '#d68f5f', dBlock: true },
  Zn: { z: 30, valence: 2, covalentRadius: 1.22, color: '#a3a9b5', dBlock: true },
  Ag: { z: 47, valence: 1, covalentRadius: 1.45, color: '#c7ccd6', dBlock: true }
};

function elementData(symbol){
  const el = ELEMENTS[symbol];
  if (!el) throw new Error('Elemento desconocido en molscene: "' + symbol + '". Agregalo a src/molscene/elements.js.');
  return el;
}

// Bohr radius in angstrom - the unit conversion between real bond lengths
// and the a0=1 scene units the orbital math is expressed in.
const ANGSTROM_PER_A0 = 0.529;


// ---- src/molscene/geometry.js ----
// Framework-agnostic 3D vector helpers + the two geometry problems the
// engine needs to solve, both handled with the same tool:
//
// 1) Where do an atom's lone pairs / unpaired electrons point, given the
//    directions of its existing bonds? (VSEPR)
// 2) Where should an atom with no explicit position go, given where its
//    already-placed neighbor is and what else is already attached to it?
//
// Both are "spread N points on a sphere away from M fixed points" - the
// same physical idea VSEPR itself is named after (electron pairs minimizing
// mutual repulsion). Solving it with literal repulsion relaxation avoids a
// hand-authored table of tetrahedral/trigonal-bipyramidal/etc angles and
// generalizes to any steric number for free.

function v3(x, y, z){ return { x, y, z }; }
function add(a, b){ return v3(a.x+b.x, a.y+b.y, a.z+b.z); }
function sub(a, b){ return v3(a.x-b.x, a.y-b.y, a.z-b.z); }
function scale(a, s){ return v3(a.x*s, a.y*s, a.z*s); }
function dot(a, b){ return a.x*b.x + a.y*b.y + a.z*b.z; }
function cross(a, b){ return v3(a.y*b.z-a.z*b.y, a.z*b.x-a.x*b.z, a.x*b.y-a.y*b.x); }
function length(a){ return Math.sqrt(dot(a, a)); }
function normalize(a){ const l = length(a); return l < 1e-9 ? v3(0,0,1) : scale(a, 1/l); }

// Deterministic point spread on a unit sphere (golden-angle spiral). Used
// as a reproducible starting guess for the relaxation below - reproducible
// on every reload is the point: a random seed here previously caused
// electrons/lone-pairs to occasionally start in an unrecoverable spot.
function fibonacciSphere(n){
  const pts = [];
  const golden = Math.PI * (3 - Math.sqrt(5));
  for (let i = 0; i < n; i++){
    const y = 1 - (i / Math.max(1, n - 1)) * 2;
    const r = Math.sqrt(Math.max(0, 1 - y*y));
    const theta = golden * i;
    pts.push(v3(Math.cos(theta)*r, y, Math.sin(theta)*r));
  }
  return pts;
}

// Solve `freeCount` unit directions that stay as far as possible from each
// other and from `fixedDirs` (which never move). This is what turns "this
// atom has 2 bonds and needs 2 lone pairs" into actual 3D directions.
function solveDirections(fixedDirs, freeCount, iterations){
  iterations = iterations || 120;
  if (freeCount === 0) return [];

  const candidates = fibonacciSphere(freeCount + fixedDirs.length + 6);
  const free = [];
  for (const c of candidates){
    if (free.length >= freeCount) break;
    const tooClose = fixedDirs.concat(free).some(function(d){ return dot(d, c) > 0.97; });
    if (!tooClose) free.push(v3(c.x, c.y, c.z));
  }
  while (free.length < freeCount) free.push(fibonacciSphere(freeCount)[free.length]);

  for (let it = 0; it < iterations; it++){
    const rate = 0.2 * (1 - it/iterations);
    const forces = free.map(function(){ return v3(0,0,0); });
    for (let i = 0; i < free.length; i++){
      const others = fixedDirs.concat(free.filter(function(_, j){ return j !== i; }));
      let f = v3(0,0,0);
      for (const o of others){
        const diff = sub(free[i], o);
        const d2 = Math.max(dot(diff, diff), 0.02);
        f = add(f, scale(diff, 1/d2));
      }
      forces[i] = f;
    }
    for (let i = 0; i < free.length; i++){
      free[i] = normalize(add(free[i], scale(forces[i], rate)));
    }
  }
  return free;
}

// A stable local perpendicular frame for a bond axis, shared by both atoms
// of the bond (both calls receive the same `axisLine`, sign-independent),
// so their leftover p orbitals (used for pi bonds) line up automatically
// instead of needing a manual sign/orientation convention per molecule.
function perpFrame(axisLine){
  const reference = Math.abs(axisLine.y) > 0.9 ? v3(1,0,0) : v3(0,1,0);
  const p1 = normalize(cross(axisLine, reference));
  const p2 = normalize(cross(axisLine, p1));
  return [p1, p2];
}

// Connected components of a graph given as a Map(node -> [neighbor, ...]).
// Every node passed in `nodes` gets a component, even with no edges (a
// singleton). Shared by metallic.js (which atoms share an electron sea)
// and clusters.js (which atoms belong to the same rigid molecule).
function connectedComponents(nodes, adjacency){
  const seen = new Set();
  const components = [];
  nodes.forEach(function(id){
    if (seen.has(id)) return;
    const comp = []; const queue = [id]; seen.add(id);
    while (queue.length){
      const cur = queue.shift(); comp.push(cur);
      (adjacency.get(cur) || []).forEach(function(n){ if (!seen.has(n)){ seen.add(n); queue.push(n); } });
    }
    components.push(comp);
  });
  return components;
}


// ---- src/molscene/roles.js ----
// What each electron-group role means: its color (used by every group
// builder) and its legend label (used by the host page). Kept as one file
// so "what does this color mean" always has a single source of truth.

const ROLE_COLORS = {
  sigma: 0xffb454,
  pi1: 0x4cd6c2,
  pi2: 0xe07de0,
  lone: 0x9d8cf0,
  radical: 0xff6b6b,
  ionicLone: 0xff7fb0,
  metallic: 0x6fd1ff
};

const ROLE_LABELS = {
  sigma: 'Enlace σ (compartido)',
  pi1: 'Enlace π',
  pi2: 'Enlace π (2)',
  lone: 'Par libre',
  radical: 'Electrón desapareado',
  ionicLone: 'Electrón transferido (iónico)',
  metallic: 'Mar de electrones (metálico)'
};


// ---- src/molscene/chemistry.js ----
// Electron bookkeeping: turns declared atoms/bonds/charges into the
// standard "steric number -> hybridization" call every intro chemistry
// course teaches (VSEPR / valence bond theory), plus lone pairs and
// leftover unpaired (radical) electrons. No 3D vectors here on purpose -
// this module only counts electrons; geometry.js/resolve.js turn the
// counts into directions.


const HYBRID_TABLE = {
  0: { label: 'none', sFrac: 1 },
  1: { label: 'none', sFrac: 1 },
  2: { label: 'sp', sFrac: 0.5 },
  3: { label: 'sp2', sFrac: 1/3 },
  4: { label: 'sp3', sFrac: 0.25 },
  5: { label: 'sp3d', sFrac: 0.2 },
  6: { label: 'sp3d2', sFrac: 1/6 }
};

function resolveChemistry(model){
  const warnings = [];
  const atomsById = new Map();
  model.atoms.forEach(function(a){ atomsById.set(a.id, { def: a, covalent: [], ionic: [], hydrogen: [], metallic: [] }); });

  model.bonds.forEach(function(b){
    const A = atomsById.get(b.a), B = atomsById.get(b.b);
    if (!A || !B) return; // already reported by the parser
    if (b.a === b.b){ warnings.push('Línea ' + b.line + ': un átomo no puede enlazarse consigo mismo.'); return; }
    const order = b.order === 'single' ? 1 : b.order === 'double' ? 2 : b.order === 'triple' ? 3 : 1;
    if (b.order === 'ionic'){
      A.ionic.push({ id: b.b, line: b.line }); B.ionic.push({ id: b.a, line: b.line });
    } else if (b.order === 'hydrogen'){
      A.hydrogen.push({ id: b.b, line: b.line }); B.hydrogen.push({ id: b.a, line: b.line });
    } else if (b.order === 'metallic'){
      A.metallic.push({ id: b.b, line: b.line }); B.metallic.push({ id: b.a, line: b.line });
    } else {
      A.covalent.push({ id: b.b, order, line: b.line }); B.covalent.push({ id: b.a, order, line: b.line });
    }
  });

  const atoms = new Map();
  atomsById.forEach(function(rec, id){
    const el = elementData(rec.def.element);
    const valenceElectrons = el.valence - rec.def.charge;
    const sigmaCount = rec.covalent.length;
    const piCount = rec.covalent.reduce(function(sum, n){ return sum + (n.order - 1); }, 0);
    const electronsInBonds = sigmaCount + piCount;

    const hasMetallic = rec.metallic.length > 0;
    let lonePairs, radicals, poolElectrons = 0;
    if (rec.def.lonepairsOverride != null){
      lonePairs = rec.def.lonepairsOverride;
      radicals = 0;
    } else {
      let remaining = valenceElectrons - electronsInBonds;
      if (remaining < 0){
        warnings.push('Átomo "' + id + '" (línea ' + rec.def.line + '): tiene más enlaces de los que sus electrones de valencia permiten; revisá el orden de enlace o la carga.');
        remaining = 0;
      }
      if (hasMetallic){
        // Electrons not already spent on covalent bonds join the shared
        // "electron sea" of the metallic cluster instead of staying as
        // this atom's own lone pairs - see metallic.js.
        poolElectrons = remaining;
        lonePairs = 0; radicals = 0;
      } else {
        lonePairs = Math.floor(remaining / 2);
        radicals = remaining % 2;
      }
    }

    const isHydrogenLike = rec.def.element === 'H' || rec.def.element === 'He';
    const stericNumber = sigmaCount === 0 ? 0 : sigmaCount + lonePairs;
    const hybrid = isHydrogenLike
      ? { label: 's', sFrac: 1 }
      : (sigmaCount === 0 ? { label: 'none', sFrac: 1 } : (HYBRID_TABLE[Math.min(6, stericNumber)] || HYBRID_TABLE[6]));

    atoms.set(id, {
      id, element: rec.def.element, charge: rec.def.charge, explicitPos: rec.def.pos,
      valenceElectrons, sigmaCount, piCount, lonePairs, radicals, poolElectrons,
      stericNumber, hybridLabel: hybrid.label, sFrac: hybrid.sFrac,
      covalent: rec.covalent, ionic: rec.ionic, hydrogen: rec.hydrogen, metallic: rec.metallic
    });
  });

  return { atoms, warnings };
}


// ---- src/molscene/layout.js ----
// Auto-layout: assigns a 3D position to every atom that didn't get an
// explicit `at (x, y, z)` in the source text, by walking the bond graph
// breadth-first and placing each new atom along one of its parent's
// free VSEPR-solved directions (geometry.js), at the real covalent (or
// ionic/hydrogen/metallic) bond length for that pair of elements.


const ORDER_LENGTH_FACTOR = { 1: 1.0, 2: 0.87, 3: 0.78 };

function bondLength(elA, elB, kind, order){
  const base = (elementData(elA).covalentRadius + elementData(elB).covalentRadius) / ANGSTROM_PER_A0;
  if (kind === 'ionic') return base * 1.15;
  if (kind === 'hydrogen') return base * 1.7;
  if (kind === 'metallic') return base * 1.05;
  return base * (ORDER_LENGTH_FACTOR[order] || 1.0);
}

function allEdges(atom){
  const out = [];
  atom.covalent.forEach(function(n){ out.push({ to: n.id, kind: 'covalent', order: n.order }); });
  atom.ionic.forEach(function(n){ out.push({ to: n.id, kind: 'ionic', order: 1 }); });
  atom.hydrogen.forEach(function(n){ out.push({ to: n.id, kind: 'hydrogen', order: 1 }); });
  atom.metallic.forEach(function(n){ out.push({ to: n.id, kind: 'metallic', order: 1 }); });
  return out;
}

function layoutPositions(chem){
  const positions = new Map();
  const visited = new Set();
  let component = 0;

  chem.atoms.forEach(function(atom, id){
    if (visited.has(id)) return;
    const root = atom.explicitPos ? v3(atom.explicitPos[0], atom.explicitPos[1], atom.explicitPos[2])
                                   : v3(component * 4.5, 0, 0);
    positions.set(id, root);
    visited.add(id);
    component++;

    const queue = [id];
    while (queue.length){
      const curId = queue.shift();
      const cur = chem.atoms.get(curId);
      const edges = allEdges(cur);
      const totalDomains = edges.length + cur.lonePairs + cur.radicals;

      for (const edge of edges){
        if (visited.has(edge.to)) continue;
        const placedDirs = edges
          .filter(function(e){ return visited.has(e.to); })
          .map(function(e){ return normalize(sub(positions.get(e.to), positions.get(curId))); });
        const free = solveDirections(placedDirs, Math.max(1, totalDomains - placedDirs.length));
        const dir = free[0] || v3(1, 0, 0);

        const neighbor = chem.atoms.get(edge.to);
        const explicit = neighbor.explicitPos;
        const pos = explicit
          ? v3(explicit[0], explicit[1], explicit[2])
          : add(positions.get(curId), scale(dir, bondLength(cur.element, neighbor.element, edge.kind, edge.order)));
        positions.set(edge.to, pos);
        visited.add(edge.to);
        queue.push(edge.to);
      }
    }
  });

  return positions;
}


// ---- src/molscene/bonds.js ----
// Turns covalent bonds into sigma/pi electron groups (real geometry: each
// hybrid orbital points straight at the actual bonded neighbor, so no
// sign convention has to be hand-picked - see docs/molscene-spec.md).
// Ionic and hydrogen bonds don't produce a shared orbital in this model;
// they only contribute a connector line for the renderer. Metallic bonds
// are handled entirely by metallic.js.


const PI_ROLES = ['pi1', 'pi2'];

function buildBondGroups(model, chem, positions){
  const groups = [];
  const connectors = [];
  const covalentBonds = [];
  const sigmaAxis = new Map();
  chem.atoms.forEach(function(_, id){ sigmaAxis.set(id, new Map()); });

  model.bonds.forEach(function(b){
    const A = chem.atoms.get(b.a), B = chem.atoms.get(b.b);
    if (!A || !B || b.order === 'metallic') return;

    if (b.order === 'ionic' || b.order === 'hydrogen'){
      connectors.push({ a: b.a, b: b.b, kind: b.order });
      return;
    }

    const order = b.order === 'single' ? 1 : b.order === 'double' ? 2 : 3;
    covalentBonds.push({ a: b.a, b: b.b, order });

    const axisLine = normalize(sub(positions.get(b.b), positions.get(b.a)));
    const dirAtoB = axisLine, dirBtoA = scale(axisLine, -1);
    sigmaAxis.get(b.a).set(b.b, dirAtoB);
    sigmaAxis.get(b.b).set(b.a, dirBtoA);

    groups.push({
      id: 'sigma:' + b.a + '-' + b.b, role: 'sigma', color: ROLE_COLORS.sigma, count: 2,
      participants: [
        { atomId: b.a, axis: dirAtoB, sFrac: A.sFrac },
        { atomId: b.b, axis: dirBtoA, sFrac: B.sFrac }
      ]
    });

    const piCount = order - 1;
    if (piCount > 0){
      perpFrame(axisLine).slice(0, piCount).forEach(function(axis, i){
        const role = PI_ROLES[i];
        groups.push({
          id: 'pi' + (i+1) + ':' + b.a + '-' + b.b, role, color: ROLE_COLORS[role], count: 2,
          participants: [
            { atomId: b.a, axis, sFrac: 0 },
            { atomId: b.b, axis, sFrac: 0 }
          ]
        });
      });
    }
  });

  return { groups, connectors, covalentBonds, sigmaAxis };
}


// ---- src/molscene/lone-pairs.js ----
// Turns each atom's leftover lone pairs / unpaired (radical) electrons
// into groups, pointed away from whatever the atom is already bonded to
// (see geometry.js's repulsion relaxation). Atoms in a metallic cluster
// never reach here with lonePairs > 0 - chemistry.js routes their
// leftover electrons into the shared pool instead (metallic.js).


function buildLoneGroups(chem, positions, sigmaAxis){
  const groups = [];

  chem.atoms.forEach(function(atom, id){
    const fixed = [];
    sigmaAxis.get(id).forEach(function(axis){ fixed.push(axis); });
    atom.ionic.forEach(function(n){ fixed.push(normalize(sub(positions.get(n.id), positions.get(id)))); });
    atom.hydrogen.forEach(function(n){ fixed.push(normalize(sub(positions.get(n.id), positions.get(id)))); });
    atom.metallic.forEach(function(n){ fixed.push(normalize(sub(positions.get(n.id), positions.get(id)))); });

    const freeCount = atom.lonePairs + atom.radicals;
    const free = solveDirections(fixed, freeCount);
    const isIonicOnly = atom.sigmaCount === 0 && atom.ionic.length > 0;

    for (let i = 0; i < atom.lonePairs; i++){
      groups.push({
        id: 'lone:' + id + ':' + i, role: isIonicOnly ? 'ionicLone' : 'lone',
        color: isIonicOnly ? ROLE_COLORS.ionicLone : ROLE_COLORS.lone, count: 2,
        participants: [{ atomId: id, axis: free[i], sFrac: atom.sFrac }]
      });
    }
    for (let i = 0; i < atom.radicals; i++){
      groups.push({
        id: 'radical:' + id + ':' + i, role: 'radical', color: ROLE_COLORS.radical, count: 1,
        participants: [{ atomId: id, axis: free[atom.lonePairs + i], sFrac: atom.sFrac }]
      });
    }
  });

  return groups;
}


// ---- src/molscene/metallic.js ----
// Metallic bonding: unlike a covalent pair, the electrons a metal atom
// gives up aren't shared with one specific neighbor - they're free to
// roam the whole cluster ("electron sea"). So instead of one group per
// bond, every metallic-connected component of atoms becomes a single
// group whose participants are *all* the atoms in that cluster, each
// contributing a plain spherical (sFrac=1) character - no bond axis, the
// point is exactly that these electrons don't belong to one direction.
//
// The sphere radius and the density's effective radius (a0) are both
// scaled from the cluster's nearest-neighbor spacing so adjacent atoms'
// spheres overlap - without that, electrons would just be trapped near
// whichever atom they started next to instead of actually roaming.


function buildMetallicGroups(model, chem, positions){
  const edges = model.bonds.filter(function(b){ return b.order === 'metallic' && chem.atoms.has(b.a) && chem.atoms.has(b.b); });
  if (edges.length === 0) return { groups: [], connectors: [] };

  const adjacency = new Map();
  edges.forEach(function(b){
    if (!adjacency.has(b.a)) adjacency.set(b.a, []);
    if (!adjacency.has(b.b)) adjacency.set(b.b, []);
    adjacency.get(b.a).push(b.b);
    adjacency.get(b.b).push(b.a);
  });

  const connectors = edges.map(function(b){ return { a: b.a, b: b.b, kind: 'metallic' }; });

  const groups = connectedComponents(Array.from(adjacency.keys()), adjacency).map(function(atomIds, idx){
    let minSpacing = Infinity;
    edges.forEach(function(b){
      if (atomIds.indexOf(b.a) === -1 || atomIds.indexOf(b.b) === -1) return;
      minSpacing = Math.min(minSpacing, length(sub(positions.get(b.a), positions.get(b.b))));
    });
    if (!isFinite(minSpacing)) minSpacing = 3;
    const radius = minSpacing * 0.62; // overlaps with same-radius neighbor spheres along every declared bond
    const a0 = minSpacing * 0.55;     // wide enough that |ψ|² stays non-negligible between adjacent nuclei

    const count = atomIds.reduce(function(sum, id){ return sum + chem.atoms.get(id).poolElectrons; }, 0);

    return {
      id: 'metallic:' + idx, role: 'metallic', color: ROLE_COLORS.metallic, count: Math.max(1, count),
      participants: atomIds.map(function(id){ return { atomId: id, axis: null, sFrac: 1, radius, a0 }; })
    };
  });

  return { groups, connectors };
}


// ---- src/molscene/clusters.js ----
// Which atoms of a resolved molecule belong to the same rigid body (i.e.
// are structurally connected). Used by reaction-scene.js: during the
// "approach" phase of a reaction animation, each original molecule moves
// as one rigid piece rather than atom-by-atom.


function computeClusters(resolved){
  const adjacency = new Map();
  resolved.atoms.forEach(function(a){ adjacency.set(a.id, []); });
  function edge(a, b){ adjacency.get(a).push(b); adjacency.get(b).push(a); }

  resolved.connectors.forEach(function(c){ edge(c.a, c.b); });
  resolved.groups.filter(function(g){ return g.role === 'sigma'; }).forEach(function(g){
    edge(g.participants[0].atomId, g.participants[1].atomId);
  });

  return connectedComponents(resolved.atoms.map(function(a){ return a.id; }), adjacency);
}


// ---- src/molscene/orbitals.js ----
// The rendering-facing orbital math: turns a resolved group/participant
// (see resolve.js) into either a probability density (for the "cloud"
// visualization mode) or a solid geometric envelope (for the "atmosphere"
// mode). Every participant is one of exactly two shapes:
//
//  - sFrac ~= 1 (pure s character - lone hydrogen, an unhybridized ion's
//    lone pair): a sphere. No axis needed.
//  - sFrac < 1 (some/all p character - a hybrid pointing at a bond or
//    lone pair, or a pure unhybridized p used for a pi bond): a pair of
//    ellipsoid lobes along `axis`, sized asymmetrically by how much s
//    character is mixed in (sFrac=0, a bare p orbital, comes out
//    perfectly symmetric; higher sFrac skews toward one big front lobe).
//
// That single rule is what lets one code path render an s orbital, a p
// orbital, and any sp^n hybrid without special-casing each one.


const A0 = 1.0;
const SPHERE_RADIUS = 1.1;
const LOBE_OFFSET = 0.38, LOBE_LONG = 0.72, LOBE_WIDE = 0.4;

function isSpherical(sFrac){ return sFrac >= 0.999; }

function lobeParams(sFrac){
  return {
    frontOffset: LOBE_OFFSET * (1 + 0.4*sFrac), frontLong: LOBE_LONG * (1 + 0.35*sFrac), frontWide: LOBE_WIDE * (1 + 0.1*sFrac),
    backOffset: LOBE_OFFSET * (1 - 0.55*sFrac), backLong: LOBE_LONG * (1 - 0.55*sFrac), backWide: LOBE_WIDE * (1 - 0.25*sFrac)
  };
}

// psi for one participant: sFrac=1 reduces to a plain s orbital (axis-
// independent); sFrac=0 reduces to a plain symmetric p orbital.
function psiParticipant(pos, nucleus, axis, sFrac, a0){
  a0 = a0 || A0;
  const d = pos.clone().sub(nucleus);
  const r = d.length();
  const t = axis ? d.dot(axis) : 0;
  const sPart = Math.sqrt(Math.max(0, sFrac));
  const pPart = Math.sqrt(Math.max(0, 1 - sFrac));
  return Math.exp(-r / a0) * (sPart + pPart * t);
}

function groupDensity(pos, participants, nucleusOf){
  let psi = 0;
  for (const p of participants) psi += psiParticipant(pos, nucleusOf(p.atomId), p.axis, p.sFrac, p.a0);
  return psi * psi;
}

function participantInside(pos, participant, nucleus){
  if (isSpherical(participant.sFrac)) return pos.distanceTo(nucleus) <= (participant.radius || SPHERE_RADIUS);
  const d = pos.clone().sub(nucleus);
  const t = d.dot(participant.axis);
  const perp = d.clone().sub(participant.axis.clone().multiplyScalar(t)).length();
  const L = lobeParams(participant.sFrac);
  const front = Math.pow((t - L.frontOffset)/L.frontLong, 2) + Math.pow(perp/L.frontWide, 2) <= 1;
  const back = Math.pow((t + L.backOffset)/L.backLong, 2) + Math.pow(perp/L.backWide, 2) <= 1;
  return front || back;
}

function groupInside(pos, participants, nucleusOf){
  return participants.some(function(p){ return participantInside(pos, p, nucleusOf(p.atomId)); });
}

function makeDotTexture(){
  const c = document.createElement('canvas'); c.width = c.height = 64;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(32,32,0,32,32,32);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.4, 'rgba(255,255,255,0.85)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g; ctx.fillRect(0,0,64,64);
  return new THREE.CanvasTexture(c);
}

function makeLabelSprite(text, color){
  const c = document.createElement('canvas'); c.width = c.height = 128;
  const ctx = c.getContext('2d');
  ctx.font = '700 ' + (text.length > 1 ? 66 : 88) + 'px Georgia, serif';
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillStyle = color;
  ctx.fillText(text, 64, 70);
  const tex = new THREE.CanvasTexture(c);
  const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false }));
  sp.scale.set(0.34, 0.34, 1);
  return sp;
}

function participantShellMeshes(participant, nucleus, colorHex){
  const meshes = [];
  const mat = function(){ return new THREE.MeshPhysicalMaterial({ color: colorHex, transparent: true, opacity: 0.15, roughness: 0.3, metalness: 0, side: THREE.DoubleSide, depthWrite: false }); };

  if (isSpherical(participant.sFrac)){
    const mesh = new THREE.Mesh(new THREE.SphereGeometry(participant.radius || SPHERE_RADIUS, 22, 22), mat());
    mesh.position.copy(nucleus);
    return [mesh];
  }

  const quat = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0,0,1), participant.axis);
  const L = lobeParams(participant.sFrac);
  [
    { offset: L.frontOffset, long: L.frontLong, wide: L.frontWide },
    { offset: -L.backOffset, long: L.backLong, wide: L.backWide }
  ].forEach(function(lobe){
    const mesh = new THREE.Mesh(new THREE.SphereGeometry(1, 18, 18), mat());
    mesh.position.copy(nucleus).add(participant.axis.clone().multiplyScalar(lobe.offset));
    mesh.quaternion.copy(quat);
    mesh.scale.set(lobe.wide, lobe.wide, lobe.long);
    meshes.push(mesh);
  });
  return meshes;
}

function randomInBox(min, max){
  return new THREE.Vector3(
    min.x + Math.random()*(max.x-min.x),
    min.y + Math.random()*(max.y-min.y),
    min.z + Math.random()*(max.z-min.z)
  );
}
function estimateMaxDensity(densityFn, boxMin, boxMax){
  let maxD = 0;
  for (let i=0;i<3000;i++){ const d = densityFn(randomInBox(boxMin,boxMax)); if (d>maxD) maxD=d; }
  return maxD*1.2 || 1e-9;
}
function rejectionCloud(densityFn, boxMin, boxMax, count){
  const maxD = estimateMaxDensity(densityFn, boxMin, boxMax);
  const pts = []; let guard = 0;
  while (pts.length < count && guard < count*500){
    guard++;
    const p = randomInBox(boxMin, boxMax);
    if (Math.random()*maxD < densityFn(p)) pts.push(p);
  }
  return pts;
}

function gaussianRandom(sigma){
  let u=0, v=0;
  while (u===0) u=Math.random();
  while (v===0) v=Math.random();
  return sigma * Math.sqrt(-2*Math.log(u)) * Math.cos(2*Math.PI*v);
}
function randGaussVec(sigma){ return new THREE.Vector3(gaussianRandom(sigma), gaussianRandom(sigma), gaussianRandom(sigma)); }

function metropolisStep(e, densityFn, sigma){
  const prop = e.pos.clone().add(randGaussVec(sigma));
  const dCur = densityFn(e.pos), dProp = densityFn(prop);
  if (dCur < 1e-10 || Math.random() < Math.min(1, dProp/dCur)) e.pos.copy(prop);
}

// Confined random walk for "atmosphere" mode, with self-recovery: if an
// electron is ever outside its own envelope (e.g. right after spawning),
// a tiny random step essentially never wanders back in on its own (the
// envelope is thin), which is what caused electrons to visibly freeze in
// earlier builds. Drifting deliberately toward a known-interior anchor
// point guarantees it always finds its way back.
function confinedStep(e, group, sigma){
  if (!group.inside(e.pos)){
    const toAnchor = group.anchor.clone().sub(e.pos);
    const dist = toAnchor.length();
    const pull = Math.min(dist, Math.max(sigma*3, 0.05));
    if (dist > 1e-6) e.pos.add(toAnchor.multiplyScalar(pull/dist));
    return;
  }
  const prop = e.pos.clone().add(randGaussVec(sigma));
  if (group.inside(prop)) e.pos.copy(prop);
}


// ---- src/molscene/parser.js ----
// Parser for the molscene text language. See docs/molscene-spec.md for the
// full grammar. Deliberately line-oriented (one statement per line) so a
// small LLM-authored snippet degrades gracefully: a mistake on one line
// produces one clear error instead of derailing the whole parse.


const RE_MOLECULE = /^molecule\s+(.+)$/i;
const RE_ATOM = /^atom\s+(\w+)\s*:\s*([A-Za-z]{1,2})\s*(.*)$/i;
const RE_BOND = /^bond\s+(\w+)\s*-\s*(\w+)\s*:\s*(single|double|triple|ionic|hydrogen|metallic)\s*(.*)$/i;
const RE_VIEW = /^view\s+(.*)$/i;
const RE_DESCRIBE = /^describe\s*$/i;
const RE_END = /^end\s*$/i;
const RE_AT = /at\s*\(\s*(-?[\d.]+)\s*,\s*(-?[\d.]+)\s*,\s*(-?[\d.]+)\s*\)/i;
const RE_CHARGE = /charge\s+(-?\d+)/i;
const RE_LONEPAIRS = /lonepairs\s+(\d+)/i;

function parseKeyValueTail(tail){
  const out = {};
  const at = tail.match(RE_AT);
  if (at) out.pos = [parseFloat(at[1]), parseFloat(at[2]), parseFloat(at[3])];
  const charge = tail.match(RE_CHARGE);
  if (charge) out.charge = parseInt(charge[1], 10);
  const lp = tail.match(RE_LONEPAIRS);
  if (lp) out.lonepairs = parseInt(lp[1], 10);
  return out;
}

function parseMolscene(text){
  const errors = [];
  const model = { name: 'molécula', description: '', atoms: [], bonds: [], view: null };
  const atomIds = new Set();

  let inDescribe = false;
  let describeLines = [];

  const lines = text.split('\n');
  for (let i = 0; i < lines.length; i++){
    const raw = lines[i];
    const line = raw.replace(/#.*$/, '').trim();
    const lineNo = i + 1;

    if (inDescribe){
      if (RE_END.test(line)){ model.description = describeLines.join('\n').trim(); inDescribe = false; describeLines = []; }
      else describeLines.push(raw);
      continue;
    }
    if (!line) continue;

    let m;
    if (RE_DESCRIBE.test(line)){ inDescribe = true; describeLines = []; continue; }
    if ((m = line.match(RE_MOLECULE))){
      model.name = m[1].trim();
      continue;
    }
    if ((m = line.match(RE_ATOM))){
      const id = m[1];
      const element = m[2][0].toUpperCase() + m[2].slice(1).toLowerCase();
      const extra = parseKeyValueTail(m[3] || '');
      if (atomIds.has(id)){
        errors.push('Línea ' + lineNo + ': átomo "' + id + '" declarado dos veces.');
        continue;
      }
      if (!ELEMENTS[element]){
        errors.push('Línea ' + lineNo + ': elemento desconocido "' + element + '". Soportados: ' + Object.keys(ELEMENTS).join(', ') + '.');
        continue;
      }
      atomIds.add(id);
      model.atoms.push({ id, element, charge: extra.charge || 0, lonepairsOverride: extra.lonepairs, pos: extra.pos || null, line: lineNo });
      continue;
    }
    if ((m = line.match(RE_BOND))){
      const a = m[1], b = m[2], order = m[3].toLowerCase();
      if (!atomIds.has(a)) errors.push('Línea ' + lineNo + ': el enlace usa "' + a + '" antes de declararlo con "atom ' + a + ': ...".');
      if (!atomIds.has(b)) errors.push('Línea ' + lineNo + ': el enlace usa "' + b + '" antes de declararlo con "atom ' + b + ': ...".');
      model.bonds.push({ a, b, order, line: lineNo });
      continue;
    }
    if ((m = line.match(RE_VIEW))){
      const tail = m[1];
      const az = tail.match(/azimuth\s+(-?[\d.]+)/i);
      const pol = tail.match(/polar\s+(-?[\d.]+)/i);
      const rad = tail.match(/radius\s+(-?[\d.]+)/i);
      model.view = {
        azimuth: az ? parseFloat(az[1]) : undefined,
        polar: pol ? parseFloat(pol[1]) : undefined,
        radius: rad ? parseFloat(rad[1]) : undefined
      };
      continue;
    }

    errors.push('Línea ' + lineNo + ': no reconocida: "' + raw.trim() + '". Se esperaba "molecule", "atom", "bond", "view" o "describe".');
  }
  if (inDescribe) errors.push('Falta "end" para cerrar el bloque "describe".');

  if (model.atoms.length === 0) errors.push('No se declaró ningún átomo (falta al menos una línea "atom ...").');

  return { model, errors };
}

const RE_REACTION = /^reaction\s+(.+)$/i;
const RE_REACTANTS = /^reactants\s*$/i;
const RE_PRODUCTS = /^products\s*$/i;

// A reaction is molscene's before/after: two independent molecule bodies
// (parsed with parseMolscene, unchanged) sharing atom ids between them so
// the renderer can animate each shared atom from its "reactants" position
// to its "products" position. Anything without a "reaction" line is just
// a regular molecule, parsed exactly as before.
function parseReactionOrMolecule(text){
  const lines = text.split('\n');
  const isReaction = lines.some(function(l){ return RE_REACTION.test(l.replace(/#.*$/, '').trim()); });
  if (!isReaction) return Object.assign({ kind: 'molecule' }, parseMolscene(text));

  let name = 'reacción';
  let description = '';
  let reactantsLines = null, productsLines = null;
  let current = null;
  let buffer = [];
  const errors = [];

  for (let i = 0; i < lines.length; i++){
    const raw = lines[i];
    const line = raw.replace(/#.*$/, '').trim();
    const lineNo = i + 1;
    if (!line){ if (current) buffer.push(''); continue; }

    if (current === null){
      let m;
      if ((m = line.match(RE_REACTION))){ name = m[1].trim(); continue; }
      if (RE_DESCRIBE.test(line)){ current = 'describe'; buffer = []; continue; }
      if (RE_REACTANTS.test(line)){ current = 'reactants'; buffer = []; continue; }
      if (RE_PRODUCTS.test(line)){ current = 'products'; buffer = []; continue; }
      errors.push('Línea ' + lineNo + ': se esperaba "describe", "reactants" o "products" para abrir un bloque de la reacción.');
      continue;
    }
    if (RE_END.test(line)){
      if (current === 'describe') description = buffer.join('\n').trim();
      else if (current === 'reactants') reactantsLines = buffer;
      else productsLines = buffer;
      current = null; buffer = [];
      continue;
    }
    buffer.push(raw);
  }
  if (current !== null) errors.push('Falta "end" para cerrar el bloque "' + current + '".');
  if (reactantsLines === null) errors.push('Falta el bloque "reactants ... end".');
  if (productsLines === null) errors.push('Falta el bloque "products ... end".');
  if (errors.length) return { kind: 'reaction', name, description, errors, reactants: null, products: null };

  const r = parseMolscene(reactantsLines.join('\n'));
  const p = parseMolscene(productsLines.join('\n'));
  r.errors.forEach(function(e){ errors.push('En "reactants": ' + e); });
  p.errors.forEach(function(e){ errors.push('En "products": ' + e); });
  if (errors.length) return { kind: 'reaction', name, description, errors, reactants: null, products: null };

  return { kind: 'reaction', name, description, errors: [], reactants: r.model, products: p.model };
}


// ---- src/molscene/resolve.js ----
// Orchestrates parser -> chemistry -> 3D. Produces a fully resolved
// "scene model": every atom has a position, every electron group (bonding,
// lone pair, radical, metallic pool) has a color, participants, and the
// axis each participant's orbital points along. orbitals.js and viewer.js
// only consume this output - they don't know about molscene syntax, and
// this file doesn't know about Three.js.
//
// A regular molecule resolves to { kind:'molecule', atoms, groups,
// connectors }. A reaction resolves to { kind:'reaction', reactants,
// products } - each side is itself a full molecule resolution, sharing
// atom ids so the renderer can animate one into the other.



function resolveModel(model){
  const chem = resolveChemistry(model);
  const positions = layoutPositions(chem);

  const atoms = Array.from(chem.atoms.values()).map(function(atom){
    return { id: atom.id, element: atom.element, charge: atom.charge, pos: positions.get(atom.id), color: elementData(atom.element).color };
  });

  const bonds = buildBondGroups(model, chem, positions);
  const lone = buildLoneGroups(chem, positions, bonds.sigmaAxis);
  const metallic = buildMetallicGroups(model, chem, positions);

  return {
    warnings: chem.warnings, name: model.name, description: model.description, atoms,
    groups: bonds.groups.concat(lone, metallic.groups),
    connectors: bonds.connectors.concat(metallic.connectors),
    bonds: bonds.covalentBonds,
    view: model.view
  };
}

function resolveMolscene(text){
  const parsed = parseReactionOrMolecule(text);

  if (parsed.kind === 'molecule'){
    if (parsed.errors.length){
      return { kind: 'molecule', errors: parsed.errors, warnings: [], atoms: [], groups: [], connectors: [], bonds: [], name: parsed.model.name, description: parsed.model.description, view: parsed.model.view };
    }
    return Object.assign({ kind: 'molecule', errors: [] }, resolveModel(parsed.model));
  }

  if (parsed.errors.length){
    return { kind: 'reaction', errors: parsed.errors, warnings: [], name: parsed.name, description: parsed.description, reactants: null, products: null };
  }

  const reactants = resolveModel(parsed.reactants);
  const products = resolveModel(parsed.products);
  const idsA = new Set(reactants.atoms.map(function(a){ return a.id; }));
  const idsB = new Set(products.atoms.map(function(a){ return a.id; }));
  const warnings = reactants.warnings.concat(products.warnings);
  idsA.forEach(function(id){ if (!idsB.has(id)) warnings.push('El átomo "' + id + '" está en "reactants" pero no en "products".'); });
  idsB.forEach(function(id){ if (!idsA.has(id)) warnings.push('El átomo "' + id + '" está en "products" pero no en "reactants".'); });

  return { kind: 'reaction', errors: [], warnings, name: parsed.name, description: parsed.description, reactants, products };
}


// ---- src/molscene/scene-build.js ----
// Turns a resolved scene model (resolve.js output) into actual Three.js
// objects: nuclei + labels + connector lines (static), and per-group
// bundles - static cloud points, atmosphere shell meshes, electron
// balls/glows, and the trail buffer they animate into (electron-motion.js
// updates these every frame; this file only allocates them once).


const CLOUD_N = 900, MAX_TRAIL = 16;

function buildAtomsAndConnectors(resolved, track, dotTexture){
  const positions = new Map(resolved.atoms.map(function(a){ return [a.id, new THREE.Vector3(a.pos.x, a.pos.y, a.pos.z)]; }));
  const nucleusOf = function(id){ return positions.get(id); };
  const nucleiSpheres = [];

  resolved.atoms.forEach(function(a){
    const pos = nucleusOf(a.id);
    const sphere = track(new THREE.Mesh(
      new THREE.SphereGeometry(0.13, 22, 22),
      new THREE.MeshStandardMaterial({ color: a.color, emissive: a.color, emissiveIntensity: 0.32, roughness: 0.45, metalness: 0.1 })
    ));
    sphere.position.copy(pos);
    nucleiSpheres.push(sphere);
    const glow = track(new THREE.Sprite(new THREE.SpriteMaterial({ map: dotTexture, color: a.color, transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending, depthWrite: false })));
    glow.position.copy(pos); glow.scale.set(0.5, 0.5, 1);
    const label = track(makeLabelSprite(a.id, '#e8ecf3'));
    label.position.copy(pos).add(new THREE.Vector3(0, 0.3, 0));
  });

  resolved.connectors.forEach(function(c){
    const a = nucleusOf(c.a), b = nucleusOf(c.b);
    if (c.kind === 'metallic'){
      track(new THREE.Line(new THREE.BufferGeometry().setFromPoints([a, b]), new THREE.LineBasicMaterial({ color: 0x3f6f8f, transparent: true, opacity: 0.35 })));
      return;
    }
    const geo = new THREE.BufferGeometry().setFromPoints([a, b]);
    const mat = new THREE.LineDashedMaterial({ color: 0x57647a, transparent: true, opacity: 0.6, dashSize: 0.08, gapSize: 0.06 });
    const line = track(new THREE.Line(geo, mat));
    line.computeLineDistances();
  });

  const sigmaGuideLines = resolved.groups.filter(function(g){ return g.role === 'sigma'; }).map(function(g){
    const a = nucleusOf(g.participants[0].atomId), b = nucleusOf(g.participants[1].atomId);
    return track(new THREE.Line(new THREE.BufferGeometry().setFromPoints([a, b]), new THREE.LineBasicMaterial({ color: 0x3a4a63, transparent: true, opacity: 0.25 })));
  });

  return { nucleusOf, nucleiSpheres, sigmaGuideLines };
}

function buildGroups(resolved, nucleusOf, track, dotTexture){
  return resolved.groups.map(function(g){
    const col = new THREE.Color(g.color);
    const participants = g.participants.map(function(p){
      return { atomId: p.atomId, sFrac: p.sFrac, radius: p.radius, a0: p.a0, axis: p.axis ? new THREE.Vector3(p.axis.x, p.axis.y, p.axis.z) : null };
    });
    const density = function(pos){ return groupDensity(pos, participants, nucleusOf); };
    const inside = function(pos){ return groupInside(pos, participants, nucleusOf); };
    const anchor = nucleusOf(participants[0].atomId).clone();

    const pts = participants.map(function(p){ return nucleusOf(p.atomId); });
    const min = pts[0].clone(), max = pts[0].clone();
    pts.forEach(function(p){ min.min(p); max.max(p); });
    min.subScalar(2.2); max.addScalar(2.2);

    const cloudPts = rejectionCloud(density, min, max, CLOUD_N);
    const positionsArr = new Float32Array(cloudPts.length * 3);
    cloudPts.forEach(function(p, i){ positionsArr[i*3]=p.x; positionsArr[i*3+1]=p.y; positionsArr[i*3+2]=p.z; });
    const cloudGeo = new THREE.BufferGeometry(); cloudGeo.setAttribute('position', new THREE.BufferAttribute(positionsArr, 3));
    const cloudMat = new THREE.PointsMaterial({ size: 0.045, map: dotTexture, color: col, transparent: true, opacity: 0.55, depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true });
    const cloudPoints = track(new THREE.Points(cloudGeo, cloudMat));

    const shellMeshes = [];
    participants.forEach(function(p){ shellMeshes.push.apply(shellMeshes, participantShellMeshes(p, nucleusOf(p.atomId), g.color).map(track)); });

    const electrons = [];
    for (let i = 0; i < g.count; i++){
      const jitter = new THREE.Vector3((Math.random()-0.5)*0.12, (Math.random()-0.5)*0.12, (Math.random()-0.5)*0.12);
      const startPos = anchor.clone().add(jitter);
      const ball = track(new THREE.Mesh(new THREE.SphereGeometry(0.05, 14, 14), new THREE.MeshStandardMaterial({ color: col, emissive: col, emissiveIntensity: 0.55, roughness: 0.35 })));
      ball.position.copy(startPos);
      const eglow = track(new THREE.Sprite(new THREE.SpriteMaterial({ map: dotTexture, color: col, transparent: true, opacity: 0.42, blending: THREE.AdditiveBlending, depthWrite: false })));
      eglow.scale.set(0.14, 0.14, 1); eglow.position.copy(startPos);
      const trail = new Array(MAX_TRAIL).fill(0).map(function(){ return startPos.clone(); });
      electrons.push({ pos: startPos, ball, glow: eglow, trail });
    }

    const trailTotal = g.count * MAX_TRAIL;
    const trailPositions = new Float32Array(trailTotal * 3), trailColors = new Float32Array(trailTotal * 3);
    const trailGeo = new THREE.BufferGeometry();
    trailGeo.setAttribute('position', new THREE.BufferAttribute(trailPositions, 3));
    trailGeo.setAttribute('color', new THREE.BufferAttribute(trailColors, 3));
    const trailMat = new THREE.PointsMaterial({ size: 0.05, map: dotTexture, vertexColors: true, transparent: true, opacity: 0.9, depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true });
    const trailPoints = track(new THREE.Points(trailGeo, trailMat));

    return { role: g.role, color: col, density, inside, anchor, cloudPoints, shellMeshes, electrons, trailPoints, trailPositions, trailColors };
  });
}


// ---- src/molscene/ball-stick.js ----
// The classic textbook look: a solid cylinder ("stick") per bond, doubled
// or tripled with a small parallel offset for double/triple bonds. No
// electrons, no orbitals - just the skeleton, for when the audience wants
// to read connectivity and geometry at a glance rather than see orbitals
// at all.


const RADIUS = 0.05;
const GAP = 0.22;
const MATERIAL = function(){ return new THREE.MeshStandardMaterial({ color: 0x2a2f38, roughness: 0.35, metalness: 0.25 }); };

function perpOffset(dir){
  const reference = Math.abs(dir.y) > 0.9 ? new THREE.Vector3(1, 0, 0) : new THREE.Vector3(0, 1, 0);
  return new THREE.Vector3().crossVectors(dir, reference).normalize();
}

function offsetsFor(order){
  if (order === 2) return [-GAP/2, GAP/2];
  if (order === 3) return [-GAP, 0, GAP];
  return [0];
}

function buildBallStick(resolved, nucleusOf, track){
  const sticks = [];
  resolved.bonds.forEach(function(b){
    const a = nucleusOf(b.a), c = nucleusOf(b.b);
    const mid = a.clone().add(c).multiplyScalar(0.5);
    const dir = c.clone().sub(a).normalize();
    const height = a.distanceTo(c);
    const quat = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
    const perp = perpOffset(dir);

    offsetsFor(b.order).forEach(function(off){
      const mesh = new THREE.Mesh(new THREE.CylinderGeometry(RADIUS, RADIUS, height, 10), MATERIAL());
      mesh.position.copy(mid).add(perp.clone().multiplyScalar(off));
      mesh.quaternion.copy(quat);
      sticks.push(track(mesh));
    });
  });
  return sticks;
}


// ---- src/molscene/camera-controls.js ----
// Orbit camera: drag to rotate, scroll to zoom, smoothed toward a target
// (azimuth, polar, radius, center) rather than snapping - both user drags
// and fitTo()/reset() calls just move the target, tick() eases toward it.


function createOrbitCamera(camera, domElement){
  let azimuth = 0.7, polar = 1.15, radius = 5.8;
  let targetAzimuth = azimuth, targetPolar = polar, targetRadius = radius;
  let center = new THREE.Vector3(0, 0, 0);
  let defaults = { azimuth, polar, radius, center: center.clone() };

  let dragging = false, lastX = 0, lastY = 0;
  domElement.addEventListener('pointerdown', function(e){
    dragging = true; lastX = e.clientX; lastY = e.clientY;
    domElement.style.cursor = 'grabbing'; domElement.setPointerCapture(e.pointerId);
  });
  domElement.addEventListener('pointermove', function(e){
    if (!dragging) return;
    const dx = e.clientX - lastX, dy = e.clientY - lastY; lastX = e.clientX; lastY = e.clientY;
    targetAzimuth -= dx * 0.006;
    targetPolar = Math.max(0.2, Math.min(Math.PI - 0.2, targetPolar - dy * 0.006));
  });
  ['pointerup', 'pointercancel', 'pointerleave'].forEach(function(ev){
    domElement.addEventListener(ev, function(){ dragging = false; domElement.style.cursor = 'grab'; });
  });
  domElement.style.cursor = 'grab';
  domElement.addEventListener('wheel', function(e){
    e.preventDefault();
    targetRadius = Math.max(2, Math.min(16, targetRadius * (1 + e.deltaY * 0.001)));
  }, { passive: false });

  function fitTo(atomPositions, view){
    const centroid = new THREE.Vector3();
    atomPositions.forEach(function(p){ centroid.add(new THREE.Vector3(p.x, p.y, p.z)); });
    centroid.divideScalar(Math.max(1, atomPositions.length));

    let maxExtent = 2;
    atomPositions.forEach(function(p){ maxExtent = Math.max(maxExtent, centroid.distanceTo(new THREE.Vector3(p.x, p.y, p.z))); });

    const rad = (view && view.radius) || Math.max(3.6, maxExtent * 2.6 + 2.2);
    defaults = { azimuth: (view && view.azimuth) || 0.7, polar: (view && view.polar) || 1.15, radius: rad, center: centroid };
    center = centroid;
    azimuth = targetAzimuth = defaults.azimuth;
    polar = targetPolar = defaults.polar;
    radius = targetRadius = defaults.radius;
  }

  function reset(){
    targetAzimuth = defaults.azimuth; targetPolar = defaults.polar; targetRadius = defaults.radius;
    center.copy(defaults.center);
  }

  function update(){
    azimuth += (targetAzimuth - azimuth) * 0.12;
    polar += (targetPolar - polar) * 0.12;
    radius += (targetRadius - radius) * 0.12;
    camera.position.set(
      center.x + radius * Math.sin(polar) * Math.cos(azimuth),
      center.y + radius * Math.cos(polar),
      center.z + radius * Math.sin(polar) * Math.sin(azimuth)
    );
    camera.lookAt(center);
  }

  return { fitTo, reset, update };
}


// ---- src/molscene/electron-motion.js ----
// Per-frame simulation: advances every visible group's electrons (Metropolis
// sampling in "cloud" mode, confined random walk in "atmosphere" mode - both
// from orbitals.js), refreshes their fading trail geometry, and applies
// mode/role visibility to the objects scene-build.js allocated.


function updateTrailGeometry(g){
  let w = 0;
  g.electrons.forEach(function(e){
    for (let i = 0; i < MAX_TRAIL; i++){
      const p = e.trail[i]; const t = i / (MAX_TRAIL - 1); const b = t * t;
      g.trailPositions[w*3]=p.x; g.trailPositions[w*3+1]=p.y; g.trailPositions[w*3+2]=p.z;
      g.trailColors[w*3]=g.color.r*b; g.trailColors[w*3+1]=g.color.g*b; g.trailColors[w*3+2]=g.color.b*b;
      w++;
    }
  });
  g.trailPoints.geometry.attributes.position.needsUpdate = true;
  g.trailPoints.geometry.attributes.color.needsUpdate = true;
}

function stepElectrons(groups, mode, speedFactor, hiddenRoles){
  if (mode === 'ballstick') return;
  const sigma = (mode === 'cloud' ? 0.16 : 0.1) * speedFactor;
  const substeps = Math.max(1, Math.round(2 * speedFactor) + 1);
  groups.forEach(function(g){
    if (hiddenRoles.has(g.role)) return;
    g.electrons.forEach(function(e){
      for (let s = 0; s < substeps; s++){
        if (mode === 'cloud') metropolisStep(e, g.density, sigma); else confinedStep(e, g, sigma);
      }
      e.ball.position.copy(e.pos); e.glow.position.copy(e.pos);
      e.trail.push(e.pos.clone()); if (e.trail.length > MAX_TRAIL) e.trail.shift();
    });
    if (mode === 'cloud') updateTrailGeometry(g);
  });
}

const BALLSTICK_SCALE = 2;

function applyVisibility(groups, mode, hiddenRoles){
  const showElectrons = mode !== 'ballstick';
  groups.forEach(function(g){
    const visible = !hiddenRoles.has(g.role);
    g.cloudPoints.visible = visible && mode === 'cloud';
    g.trailPoints.visible = visible && mode === 'cloud';
    g.shellMeshes.forEach(function(m){ m.visible = visible && mode === 'atmosphere'; });
    g.electrons.forEach(function(e){ e.ball.visible = visible && showElectrons; e.glow.visible = visible && showElectrons; });
  });
}

// The skeleton (nuclei + sticks), separate from the electron groups above:
// bigger nuclei and solid bond cylinders only in "ballstick" mode, the
// thin per-bond guide line only when something else (a cloud/shell) is
// already showing where the bond is.
function applyDecorMode(decor, mode){
  const isBallStick = mode === 'ballstick';
  decor.nucleiSpheres.forEach(function(s){ s.scale.setScalar(isBallStick ? BALLSTICK_SCALE : 1); });
  decor.sigmaGuideLines.forEach(function(l){ l.visible = !isBallStick; });
  decor.stickMeshes.forEach(function(m){ m.visible = isBallStick; });
}


// ---- src/molscene/reaction-scene.js ----
// Builds the Three.js objects for a reaction's two phases:
//
//  - one rigid THREE.Group per original reactant molecule (a "cluster",
//    see clusters.js), each holding its own static nuclei/orbitals built
//    in local coordinates around that molecule's centroid, so animating
//    the group's position moves the whole molecule as one rigid piece
//    (see reaction-motion.js for the actual approach animation);
//  - one static group for the resolved product structure, shifted so its
//    centroid lands wherever the reactant clusters are converging to.
//
// Both reuse buildAtomsAndConnectors/buildGroups unchanged - a "local"
// resolved model (atoms re-centered on an origin, groups/connectors
// filtered to the relevant atoms) looks exactly like a normal resolved
// molecule to those functions.


function centroidOf(atoms){
  const v = new THREE.Vector3();
  atoms.forEach(function(a){ v.add(new THREE.Vector3(a.pos.x, a.pos.y, a.pos.z)); });
  return v.divideScalar(Math.max(1, atoms.length));
}

function localize(resolved, ids, origin){
  const idSet = new Set(ids);
  const atoms = resolved.atoms.filter(function(a){ return idSet.has(a.id); }).map(function(a){
    return { id: a.id, element: a.element, charge: a.charge, color: a.color,
      pos: { x: a.pos.x - origin.x, y: a.pos.y - origin.y, z: a.pos.z - origin.z } };
  });
  const groups = resolved.groups.filter(function(g){ return g.participants.every(function(p){ return idSet.has(p.atomId); }); });
  const connectors = resolved.connectors.filter(function(c){ return idSet.has(c.a) && idSet.has(c.b); });
  const bonds = resolved.bonds.filter(function(b){ return idSet.has(b.a) && idSet.has(b.b); });
  return { atoms, groups, connectors, bonds };
}

function buildRig(resolved, ids, origin, track, dotTexture){
  const group = new THREE.Group();
  group.position.copy(origin);
  track(group);
  const localTrack = function(o){ group.add(o); return o; };
  const local = localize(resolved, ids, origin);
  const built = buildAtomsAndConnectors(local, localTrack, dotTexture);
  const groups = buildGroups(local, built.nucleusOf, localTrack, dotTexture);
  const stickMeshes = buildBallStick(local, built.nucleusOf, localTrack);
  const decor = { nucleiSpheres: built.nucleiSpheres, sigmaGuideLines: built.sigmaGuideLines, stickMeshes };
  return { group, groups, decor };
}

function buildClusterRigs(resolved, track, dotTexture){
  return computeClusters(resolved).map(function(ids){
    const origin = centroidOf(resolved.atoms.filter(function(a){ return ids.indexOf(a.id) !== -1; }));
    const rig = buildRig(resolved, ids, origin, track, dotTexture);
    return { group: rig.group, groups: rig.groups, decor: rig.decor, start: origin.clone() };
  });
}

function buildProductRig(resolved, track, dotTexture, convergencePoint){
  const allIds = resolved.atoms.map(function(a){ return a.id; });
  const origin = centroidOf(resolved.atoms);
  const rig = buildRig(resolved, allIds, origin, track, dotTexture);
  rig.group.position.copy(convergencePoint);
  return rig;
}



// ---- src/molscene/reaction-motion.js ----
// Drives a reaction's timeline (t: 0 -> 1). Approach (t < 0.5): each
// reactant cluster eases toward the point where the product will appear.
// Around that same midpoint, instead of an instant visibility swap, the
// reactant clusters shrink toward their own centroid while the (already
// built, static) product grows from its centroid, overlapping - the two
// read as dissolving into one another rather than a hard cut, with a
// small, brief, warm-toned spark (not a flash) marking the instant.

function smoothstep(t){ return t * t * (3 - 2 * t); }
function clamp01(x){ return Math.max(0, Math.min(1, x)); }

const APPROACH_END = 0.5;
const MORPH_START = 0.42, MORPH_END = 0.58;
const IMPACT_T = 0.5;

function updateReactionRig(rig, t){
  const approach = smoothstep(clamp01(t / APPROACH_END));
  rig.clusterRigs.forEach(function(c){ c.group.position.lerpVectors(c.start, rig.convergence, approach); });

  const morph = smoothstep(clamp01((t - MORPH_START) / (MORPH_END - MORPH_START)));
  const clusterScale = Math.max(0.001, 1 - morph);
  rig.clusterRigs.forEach(function(c){
    c.group.scale.setScalar(clusterScale);
    c.group.visible = clusterScale > 0.002;
  });
  const productScale = Math.max(0.001, morph);
  rig.productRig.group.scale.setScalar(productScale);
  rig.productRig.group.visible = productScale > 0.002;

  if (rig.flash){
    const d = Math.abs(t - IMPACT_T);
    const w = 0.09;
    rig.flash.material.opacity = d < w ? (1 - d / w) * 0.35 : 0;
  }
}

function activeReactionGroups(rig, t){
  if (t >= IMPACT_T) return rig.productRig.groups;
  const out = [];
  rig.clusterRigs.forEach(function(c){ out.push.apply(out, c.groups); });
  return out;
}


// ---- src/molscene/viewer.js ----
// Public entry point of the engine: takes molscene text and a DOM element,
// renders the 3D scene into it, and returns a small controller for the
// host page to drive (mode, play/pause, speed, which electron groups are
// visible, and - for a reaction - playback of the approach/bonding
// animation) and to read a legend from. The host page owns its own UI
// chrome; this module delegates to camera-controls.js / scene-build.js /
// electron-motion.js / reaction-scene.js / reaction-motion.js for anything
// beyond top-level wiring.


const REACTION_DURATION_S = 6;

function createViewer(container){
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x070a10);
  const camera = new THREE.PerspectiveCamera(45, 1, 0.1, 100);
  const renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setClearColor(0x070a10, 1);
  container.appendChild(renderer.domElement);

  scene.add(new THREE.AmbientLight(0x8fa5c9, 0.55));
  const key = new THREE.PointLight(0xffffff, 1.1, 30); key.position.set(2.8, 3, 3.5); scene.add(key);
  const fill = new THREE.PointLight(0x5b7fd6, 0.35, 30); fill.position.set(-3, -2, -2); scene.add(fill);

  const dotTexture = makeDotTexture();
  const orbitCamera = createOrbitCamera(camera, renderer.domElement);

  let sceneObjects = [];
  let staticGroups = [];
  let staticDecor = null;
  let reaction = null;
  let mode = 'cloud';
  let playing = !window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  let speedFactor = 1;
  let hiddenRoles = new Set();

  function clearScene(){
    sceneObjects.forEach(function(o){ scene.remove(o); if (o.geometry) o.geometry.dispose(); if (o.material) o.material.dispose(); });
    sceneObjects = [];
  }
  function track(o){ scene.add(o); sceneObjects.push(o); return o; }
  function currentGroups(){ return reaction ? activeReactionGroups(reaction, reaction.t) : staticGroups; }
  function currentDecors(){
    if (!reaction) return staticDecor ? [staticDecor] : [];
    return reaction.clusterRigs.map(function(c){ return c.decor; }).concat([reaction.productRig.decor]);
  }
  function refreshVisibility(){
    applyVisibility(currentGroups(), mode, hiddenRoles);
    currentDecors().forEach(function(d){ applyDecorMode(d, mode); });
  }

  function makeFlash(){
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: dotTexture, color: 0xffb454, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false }));
    sprite.scale.set(0.7, 0.7, 1);
    return track(sprite);
  }

  function load(text){
    clearScene();
    const resolved = resolveMolscene(text);
    if (resolved.errors.length){ staticGroups = []; staticDecor = null; reaction = null; return resolved; }

    if (resolved.kind === 'reaction'){
      const convergence = centroidOf(resolved.reactants.atoms);
      const clusterRigs = buildClusterRigs(resolved.reactants, track, dotTexture);
      const productRig = buildProductRig(resolved.products, track, dotTexture, convergence);
      const flash = makeFlash();
      flash.position.copy(convergence);
      reaction = { clusterRigs, productRig, convergence, flash, t: 0, playing: false };
      staticGroups = []; staticDecor = null;
      updateReactionRig(reaction, 0);
      orbitCamera.fitTo(resolved.reactants.atoms.map(function(a){ return a.pos; }), resolved.reactants.view || resolved.products.view);
    } else {
      reaction = null;
      const built = buildAtomsAndConnectors(resolved, track, dotTexture);
      staticGroups = buildGroups(resolved, built.nucleusOf, track, dotTexture);
      const stickMeshes = buildBallStick(resolved, built.nucleusOf, track);
      staticDecor = { nucleiSpheres: built.nucleiSpheres, sigmaGuideLines: built.sigmaGuideLines, stickMeshes };
      orbitCamera.fitTo(resolved.atoms.map(function(a){ return a.pos; }), resolved.view);
    }
    refreshVisibility();
    return resolved;
  }

  function resize(){
    const w = container.clientWidth, h = container.clientHeight;
    if (!w || !h) return;
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(w, h, false);
    camera.aspect = w / h; camera.updateProjectionMatrix();
  }
  new ResizeObserver(resize).observe(container);
  resize();

  let lastTime = performance.now();
  function tick(){
    requestAnimationFrame(tick);
    const now = performance.now();
    const dt = Math.min(0.05, (now - lastTime) / 1000);
    lastTime = now;

    orbitCamera.update();

    if (reaction && reaction.playing){
      reaction.t = Math.min(1, reaction.t + dt / REACTION_DURATION_S);
      if (reaction.t >= 1) reaction.playing = false;
      updateReactionRig(reaction, reaction.t);
      refreshVisibility();
    }
    if (playing) stepElectrons(currentGroups(), mode, speedFactor, hiddenRoles);

    renderer.render(scene, camera);
  }
  tick();

  return {
    load,
    setMode: function(m){ mode = m; refreshVisibility(); },
    setPlaying: function(p){ playing = p; },
    setSpeed: function(f){ speedFactor = f; },
    setRoleHidden: function(role, hidden){ if (hidden) hiddenRoles.add(role); else hiddenRoles.delete(role); refreshVisibility(); },
    resetCamera: function(){ orbitCamera.reset(); },
    isReaction: function(){ return !!reaction; },
    playReaction: function(){ if (!reaction) return; reaction.t = 0; reaction.playing = true; updateReactionRig(reaction, 0); refreshVisibility(); },
    setReactionProgress: function(t){ if (!reaction) return; reaction.playing = false; reaction.t = Math.min(1, Math.max(0, t)); updateReactionRig(reaction, reaction.t); refreshVisibility(); },
    getReactionProgress: function(){ return reaction ? reaction.t : 0; },
    getLegend: function(){
      const seen = new Map();
      currentGroups().forEach(function(g){
        if (!seen.has(g.role)) seen.set(g.role, { role: g.role, label: ROLE_LABELS[g.role] || g.role, color: '#' + g.color.getHexString(), count: 0 });
        seen.get(g.role).count += g.electrons.length;
      });
      return Array.from(seen.values());
    }
  };
}


export { createViewer, ROLE_LABELS, resolveMolscene };
